/**
 * Bearer credential for the Nerova connector. The secret Nerova presents is
 * generated by us and stored in Nerova (write-only) and, here, only as SHA-256
 * hashes in NEROVA_CONNECTOR_TOKEN_HASHES (comma-separated, so two hashes
 * allow a zero-downtime rotation). The plaintext never reaches env or logs.
 * An unset or empty list disables the connector (fail closed).
 */
import { safeEqual, sha256Hex } from '@booking/features/lib/crypto.ts';

/** The slice of the API environment the connector reads. apps/api's Env is assignable to it. */
export interface ConnectorEnv {
  readonly NEROVA_CONNECTOR_TOKEN_HASHES?: string | undefined;
}

const HASH_RE = /^[0-9a-f]{64}$/;

export function configuredTokenHashes(env: ConnectorEnv): string[] {
  return (env.NEROVA_CONNECTOR_TOKEN_HASHES ?? '')
    .split(',')
    .map((h) => h.trim().toLowerCase())
    .filter((h) => HASH_RE.test(h));
}

export function extractBearer(header: string | undefined): string | null {
  const match = /^Bearer\s+(\S+)\s*$/i.exec(header ?? '');
  return match?.[1] ?? null;
}

/** Compares against every configured hash (no early exit) so timing does not reveal which matched. */
export function isValidConnectorToken(token: string | null, env: ConnectorEnv): boolean {
  const hashes = configuredTokenHashes(env);
  if (!token || hashes.length === 0) return false;
  const presented = sha256Hex(token);
  let ok = false;
  for (const hash of hashes) ok = safeEqual(presented, hash) || ok;
  return ok;
}
